import type { ConnectedItem } from "./service";

const CLOSET_CO_WEAR_NOTE_RE = /^(?:Worn in |Co-worn together in )/i;

/**
 * Returns true when a connection edge represents a structural Closet garment <-> outfit wear log (`WORN_ON`).
 */
export function isWearLogConnection(conn: ConnectedItem): boolean {
  return conn.connectionType === "WORN_ON";
}

/**
 * Returns true when a `PAIRED_WITH` edge was auto-generated by Closet co-wear sync
 * (`"Worn in ..."` or legacy `"Co-worn together in ..."`), keeping manual pairings intact.
 */
export function isAutoClosetCoWearConnection(conn: ConnectedItem): boolean {
  if (conn.connectionType !== "PAIRED_WITH") return false;
  if (typeof conn.contextNote !== "string") return false;
  return CLOSET_CO_WEAR_NOTE_RE.test(conn.contextNote.trim());
}

export interface PartitionedConnections {
  wearLinks: ConnectedItem[];
  autoCoWearPairs: ConnectedItem[];
  curatedPairs: ConnectedItem[];
}

/**
 * Partitions connections into structural Closet wear logs (`WORN_ON`),
 * auto-synced Closet co-wear pairs, and curated Synaptic Pairs.
 */
export function partitionConnections(
  connections: readonly ConnectedItem[] = []
): PartitionedConnections {
  const wearLinks: ConnectedItem[] = [];
  const autoCoWearPairs: ConnectedItem[] = [];
  const curatedPairs: ConnectedItem[] = [];

  for (const conn of connections) {
    if (isWearLogConnection(conn)) {
      wearLinks.push(conn);
    } else if (isAutoClosetCoWearConnection(conn)) {
      autoCoWearPairs.push(conn);
    } else {
      curatedPairs.push(conn);
    }
  }

  return { wearLinks, autoCoWearPairs, curatedPairs };
}
